using System.Net.Http.Json;
using System.Text.Json;
using BrewNest.Contracts.Sales;
using BrewNest.Web.Services;

namespace BrewNest.Web.Features.Sales.Services;

internal sealed class SalesApiClient(HttpClient httpClient)
{
    private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);
    public Task<SalesOrderResponse[]> GetOrdersAsync()=>GetAsync<SalesOrderResponse[]>("api/sales/orders");public Task<SalesOrderResponse> GetOrderAsync(Guid id)=>GetAsync<SalesOrderResponse>($"api/sales/orders/{id}");public Task<SalesReferenceDataResponse> GetReferencesAsync()=>GetAsync<SalesReferenceDataResponse>("api/sales/references");public Task<SalesStatusHistoryResponse[]> GetHistoryAsync(Guid id)=>GetAsync<SalesStatusHistoryResponse[]>($"api/sales/status-history?orderId={id}");
    public Task<SalesOrderResponse> CreateAsync(CreateSalesOrderRequest x)=>PostAsync<SalesOrderResponse>("api/sales/orders",x);public Task<SalesOrderResponse> AddLineAsync(Guid id,AddSalesOrderLineRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/lines",x);public Task<SalesOrderResponse> UpdateLineAsync(Guid id,Guid lineId,UpdateSalesOrderLineRequest x)=>PutAsync<SalesOrderResponse>($"api/sales/orders/{id}/lines/{lineId}",x);public Task<SalesOrderResponse> RequestDiscountAsync(Guid id,RequestSalesDiscountRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/discounts",x);public Task<SalesOrderResponse> DecideDiscountAsync(Guid id,Guid discountId,DecideSalesDiscountRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/discounts/{discountId}/decision",x);
    public Task<SalesOrderResponse> ConfirmAsync(Guid id,ChangeSalesOrderStatusRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/confirm",x);public Task<SalesOrderResponse> BillAsync(Guid id,ChangeSalesOrderStatusRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/bill",x);public Task<SalesOrderResponse> CloseAsync(Guid id,ChangeSalesOrderStatusRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/close",x);public Task<SalesOrderResponse> CancelAsync(Guid id,ChangeSalesOrderStatusRequest x)=>PostAsync<SalesOrderResponse>($"api/sales/orders/{id}/cancel",x);
    private async Task<T> GetAsync<T>(string uri){try{using var response=await httpClient.GetAsync(uri);return await ReadAsync<T>(response);}catch(HttpRequestException ex){throw Unavailable(ex);}}private async Task<T> PostAsync<T>(string uri,object value){try{using var response=await httpClient.PostAsJsonAsync(uri,value,JsonOptions);return await ReadAsync<T>(response);}catch(HttpRequestException ex){throw Unavailable(ex);}}private async Task<T> PutAsync<T>(string uri,object value){try{using var response=await httpClient.PutAsJsonAsync(uri,value,JsonOptions);return await ReadAsync<T>(response);}catch(HttpRequestException ex){throw Unavailable(ex);}}
    private static async Task<T> ReadAsync<T>(HttpResponseMessage response){if(!response.IsSuccessStatusCode)throw await ErrorAsync(response);return await response.Content.ReadFromJsonAsync<T>(JsonOptions)??throw new SalesApiException("The Sales API returned an empty response.");}private static async Task<SalesApiException> ErrorAsync(HttpResponseMessage response)=>new(ApiProblemMessage.Read(await response.Content.ReadAsStringAsync(),response.StatusCode,"Sales"));private static SalesApiException Unavailable(HttpRequestException ex)=>new("The café server is unavailable. Please check your connection and try again.",ex);
}
internal sealed class SalesApiException:Exception { public SalesApiException(string message):base(message){}public SalesApiException(string message,Exception inner):base(message,inner){} }
